export const BODY: string = "\n<p>لایٔ آؤٹ کولاج میں پہلا فیصلہ ہوتا ہے، اور یہ اس کے بعد سب کچھ طے کرتا ہے۔ گرڈ کہتا ہے کہ تصاویر برابر ہیں۔ پٹی کہتی ہے کہ وہ ترتیب ہیں۔ موڈ بورڈ کہتا ہے کہ وہ احساس ہیں۔</p>\n<p>اس گائیڈ میں امیج کولاج میکر کے لے آؤٹس کا موازنہ کیا گیا ہے: 2 بائی 2 اور 3 بائی 3 گرڈ، عمودی اور افقی پٹیاں، اور ان سے بنے آزاد انداز۔</p>\n<p>اپنا اگلا کولاج بنانے سے پہلے اسے پڑھیں۔ مقصد کے لیے چنا گیا لے آؤٹ کولاج کو فوراً پڑھنے کے قابل بنا دیتا ہے، جبکہ بے ترتیب چنا گیا لے آؤٹ دیکھنے والے کو الجھاتا ہے۔</p>\n<h2 id=\"why-layout-matters\">لے آؤٹ کیوں اہمیت رکھتا ہے</h2>\n<p>لے آؤٹ پڑھنے کی ترتیب ہوتی ہے۔ آنکھ کولاج میں اوپر بائیں سے داخل ہوتی ہے، اوپر والی قطار پر چلتی ہے، اور نیچے کام کرتی ہے، بالکل صفحہ پڑھنے کی طرح۔ لے آؤٹ طے کرتا ہے کہ کیا پہلے دیکھا جائے۔</p>\n<p>گرڈ ہر تصویر کو برابر وزن دیتا ہے، اس لیے دیکھنے والا آباد ہونے سے پہلے پورا سیٹ اسکین کرتا ہے۔ پٹی تصاویر کو ترتیب دیتی ہے، اس لیے دیکھنے والا انہیں ترتیب سے دیکھتا ہے۔</p>\n<p>لے آؤٹ تیار تصویر کی شکل بھی طے کرتا ہے۔ گرڈ مربع بناتا ہے، عمودی پٹی پورٹریٹ بناتی ہے، اور افقی پٹی چوڑا بینر بناتی ہے۔ شکل منزل سے ملنی چاہیے۔</p>\n<p>لے آؤٹ کہانی کے لیے چنیں، تصاویر کی تعداد کے لیے نہیں۔ واضح ہیرو والا سفر فیچر لے آؤٹ کا حقدار ہے، برابر لمحوں کا سیٹ گرڈ کا حقدار ہے، اور احساس موڈ بورڈ کا حقدار ہے۔</p>\n<h2 id=\"the-2x2-grid\">2 بائی 2 گرڈ</h2>\n<p>2 بائی 2 گرڈ چار تصاویر کو مربع میں رکھتا ہے، اور یہ سب سے سادہ کولاج ہے۔ چار برابر سیل، ایک مربع تصویر، اور سنبھالنے کے لیے کوئی درجہ بندی نہیں۔ یہ شروع کرنے کی جگہ ہے۔</p>\n<p>چار تصاویر سیٹ دکھانے کے لیے کافی ہوتی ہیں بغیر دیکھنے والے کو مغلوب کیے۔ چار زاویوں والی پروڈکٹ، چار تفصیل والا کمرہ، یا چار لمحوں والا دن سب اس میں فٹ ہو جاتے ہیں۔</p>\n<p>2 بائی 2 گرڈ ملی ہوئی سمت کے لیے سب سے معاف کرنے والا لے آؤٹ ہے۔ پورٹریٹ اور لینڈ اسکیپ تصویر عجیب کراپ کے بغیر گرڈ شیئر کر سکتی ہیں، کیونکہ ہر سیل مربع ہوتا ہے۔</p>\n<p>پہلے کولاج کے لیے 2 بائی 2 گرڈ استعمال کریں۔ اسے ترتیب دینا آسان، متوازن کرنا آسان، اور غلط کرنا مشکل ہے۔ 3 بائی 3 گرڈ پانچ مزید فیصلے بڑھاتا ہے، جبکہ 2 بائی 2 چار تصویروں پر مرکوز رہتا ہے۔</p>\n<h2 id=\"the-3x3-grid\">3 بائی 3 گرڈ</h2>\n<p>3 بائی 3 گرڈ نو تصاویر کو مربع میں رکھتا ہے، اور یہ پورے سیٹ کے لیے لے آؤٹ ہے۔ نو مضبوط تصاویر والا سفر، تقریب، یا پروڈکٹ رینج گرڈ کو بھر دیتا ہے۔</p>\n<p>نو تصاویر کو نو مضبوط تصاویر چاہیے ہوتی ہیں۔ تین بہترین تصاویر اور چھ بھرنے والی تصاویر والا گرڈ چار بہترین تصاویر والے 2 بائی 2 گرڈ سے بدتر لگتا ہے، کیونکہ کمزور تصاویر نظر آتی ہیں۔</p>\n<p>بیچ والا سیل 3 بائی 3 گرڈ کا قدرتی مرکز ہوتا ہے۔ آنکھ کنارے اسکین کرنے کے بعد وہاں آتی ہے، اس لیے ہیرو تصویر بیچ میں یا اوپر بیچ میں ہونی چاہیے۔</p>\n<p>گرڈ کو ہلکی اور تاریک تصاویر کو یکساں پھیلا کر متوازن کریں۔ ایک کونے میں جمع تین تاریک تصاویر گرڈ کو وہاں بھاری محسوس کراتی ہیں، جبکہ وہی تین پھیلی ہوئی متوازن لگتی ہیں۔</p>\n<h2 id=\"vertical-strips\">عمودی پٹیاں</h2>\n<p>عمودی پٹی تصاویر کو لمبے کالم میں ڈھیر کرتی ہے، اوپر سے نیچے پڑھی جاتی ہے۔ یہ ترتیب کے لیے موزوں ہے: صبح، دوپہر، اور شام؛ مرحلہ ایک، دو، اور تین؛ یا سفر کی شروعات سے اختتام تک۔</p>\n<p>عمودی پٹیاں پورٹریٹ کینوس کے لیے موزوں ہیں، جو اسٹوری اور فون اسکرین کے لیے موزوں ہیں۔ لمبا کولاج فون اسکرین کو قدرتی طور پر بھرتا ہے، اور دیکھنے والا اسے اسکرول کرتے ہوئے دیکھتا ہے۔</p>\n<p>پٹی بہت سی تصاویر رکھ سکتی ہے، مگر تعداد بڑھنے پر ہر ایک تنگ ہو جاتی ہے۔ تین سے پانچ تصاویر عملی حد ہیں: ترتیب کے لیے کافی، اور اتنی کم کہ ہر تصویر نظر آئے۔</p>\n<p>پٹی کو احتیاط سے ترتیب دیں، کیونکہ ترتیب ہی مقصد ہے۔ بے ترتیب پڑھی گئی پٹی کہانی کو الجھاتی ہے، جبکہ ترتیب والی پٹی آسانی سے پڑھی جاتی ہے۔ بہترین تصویر پہلے رکھیں۔</p>\n<h2 id=\"horizontal-strips\">افقی پٹیاں</h2>\n<p>افقی پٹی تصاویر کو چوڑی قطار میں لگاتی ہے، بائیں سے دائیں پڑھی جاتی ہے۔ یہ ٹائم لائن، لمحوں کا پینوراما، یا موازنے کے لیے موزوں ہے جہاں دیکھنے والا پار اسکین کرتا ہے۔</p>\n<p>افقی پٹیاں چوڑے کینوس کے لیے موزوں ہیں، جو بینر، ہیڈر، اور ویب سائٹ فیچر کے لیے موزوں ہیں۔ صفحے کے اوپر چوڑا کولاج پروڈکٹ رینج یا سفر کا تعارف کراتا ہے۔</p>\n<p>پٹی پہلے اور بعد کے موازنے کے لیے اچھی کام کرتی ہے، جہاں دو یا تین تصاویر ساتھ بیٹھتی ہیں اور تبدیلی ایک نظر میں نظر آتی ہے۔ تزئین و آرائش، میک اوور، یا پروڈکٹ تبدیلی سب اس میں فٹ ہوتی ہیں۔</p>\n<p>پٹی کو مختصر رکھیں۔ دو سے چار تصاویر عملی حد ہیں، کیونکہ تعداد بڑھنے پر ہر تصویر تنگ ہو جاتی ہے۔ آٹھ تصاویر والی پٹی تھمب نیل کی قطار بن جاتی ہے۔</p>\n<h2 id=\"mood-boards\">موڈ بورڈ</h2>\n<p>موڈ بورڈ وہ کولاج ہے جو واقعے کے بجائے احساس کے گرد بنتا ہے۔ یہ رنگ، بناوٹ، اور تصاویر جمع کرتا ہے جو ایک مزاج شیئر کرتے ہیں: پرسکون بیڈروم، بولڈ برانڈ، یا خزاں کی شام۔</p>\n<p>موڈ بورڈ گرڈ سے بنائیں، عام طور پر 3 بائی 3، اور تصاویر، رنگ نمونے، اور بناوٹ ملائیں۔ تنوع ہی مقصد ہے: کپڑے کا قریبی شاٹ، لینڈ اسکیپ، رنگ کارڈ، اور تفصیل سب ساتھ بیٹھتے ہیں۔</p>\n<p>بورڈ کو ساتھ رکھنے کے لیے مستقل خلا اور پس منظر رنگ استعمال کریں۔ ملی ہوئی تصاویر والے موڈ بورڈ کو مستحکم فریم چاہیے ہوتا ہے، ورنہ یہ بے ترتیب تصاویر میں بکھر جاتا ہے۔</p>\n<p>موڈ بورڈ ڈیزائنرز، اسٹائلسٹ، اور منصوبہ سازوں کے لیے کام کے اوزار ہیں۔ جو کلائنٹ موڈ بورڈ دیکھتا ہے وہ مکمل ٹکڑا بننے سے پہلے سمت سمجھ جاتا ہے۔</p>\n<h2 id=\"story-layouts\">کہانی والے لے آؤٹ</h2>\n<p>کہانی والا لے آؤٹ وہ کولاج ہے جو بیانیہ کے طور پر ترتیب دیا گیا ہو: شروعات، درمیان، اور اختتام۔ یہ پٹی یا گرڈ استعمال کرتا ہے جس میں واضح پڑھنے کی ترتیب ہو، تاکہ دیکھنے والا کہانی کی پیروی کرے۔</p>\n<p>وقت میں بتائی گئی کہانی کے لیے عمودی پٹی استعمال کریں، شروعات اوپر اور اختتام نیچے۔ دن کا سفر، ترکیب، یا پروجیکٹ تعمیر سب قدرتی طور پر پڑھتے ہیں۔</p>\n<p>لمحے کے گرد بتائی گئی کہانی کے لیے فیچر تصویر والا گرڈ استعمال کریں۔ فیچر تصویر عروج ہوتی ہے، اور چھوٹی تصاویر سیاق ہوتی ہیں: جگہ، لوگ، اور تفصیل۔</p>\n<p>کہانی کو مختصر رکھیں۔ کہانی کے لیے تین سے پانچ تصاویر کافی ہوتی ہیں، اس سے زیادہ ہو تو دیکھنے والا دھاگہ کھو دیتا ہے۔ کہانی کولاج نمایاں ریل ہوتی ہے، مکمل البم نہیں۔</p>\n<h2 id=\"before-and-after-layouts\">پہلے اور بعد والے لے آؤٹ</h2>\n<p>پہلے اور بعد والا کولاج تبدیلی دکھاتا ہے، اور لے آؤٹ کو تبدیلی کو واضح بنانا چاہیے۔ افقی پٹی قدرتی انتخاب ہے: پہلے بائیں، بعد دائیں۔</p>\n<p>صرف دو تصاویر استعمال کریں، یا درمیانی مرحلے کے ساتھ تین۔ نو تصاویر والا پہلے اور بعد تبدیلی کو گرڈ میں دفن کر دیتا ہے، جبکہ ساتھ والی دو تصاویر اسے ناممکن بنا دیتی ہیں کہ اسے نہ دیکھا جائے۔</p>\n<p>دونوں تصاویر کی فریمنگ ملائیں۔ ایک ہی زاویہ، ایک ہی کراپ، اور ایک ہی روشنی تبدیلی کو نمایاں کرتی ہے، جبکہ مختلف زاویے دیکھنے والے کو موازنے کے بجائے فرق تلاش کرنے پر مجبور کرتے ہیں۔</p>\n<p>جب تبدیلی معمولی ہو تو تصاویر کو لیبل کریں۔ چھوٹا کیپشن یا متن اوورلے جو پہلے اور بعد کہے تمام شک دور کر دیتا ہے، خاص طور پر پروڈکٹ یا تزئین و آرائش کے لیے۔</p>\n<h2 id=\"feature-photo-layouts\">فیچر تصویر والے لے آؤٹ</h2>\n<p>فیچر تصویر والا لے آؤٹ ایک سیل کو باقی سے بڑا کرتا ہے، اور کولاج کو واضح مرکز دیتا ہے۔ آنکھ پہلے بڑی تصویر پر آتی ہے، پھر چھوٹی تصاویر کو دیکھتی ہے۔</p>\n<p>اسے گرڈ میں تقسیم ایڈجسٹ کر کے بنائیں، ہیرو سیل کو بڑا اور اس کے پڑوسیوں کو چھوٹا کر کے۔ ایک بڑے سیل والا 2 بائی 2 گرڈ شوکیس لگتا ہے، جبکہ برابر سیل والا گرڈ سیٹ لگتا ہے۔</p>\n<p>فیچر کو موضوع کے ساتھ ساتھ کوالٹی سے بھی چنیں۔ ہیرو سیٹ کی سب سے تیز، سب سے روشن تصویر ہونی چاہیے، کیونکہ کمزور تصویر کو بڑا کرنا صرف اس کی خامیاں کھینچتا ہے۔</p>\n<p>فیچر کو ایک تصویر تک رکھیں۔ دو بڑے سیل ایک دوسرے سے مقابلہ کرتے ہیں اور درجہ بندی گر جاتی ہے، اس لیے ایک سیل کو واضح بڑا کریں اور باقی کو چھوٹا چھوڑیں۔</p>\n<h2 id=\"borderless-collages\">بغیر سرحد والے کولاج</h2>\n<p>بغیر سرحد والا کولاج خلا کو صفر سیٹ کرتا ہے، اس لیے تصاویر چھوتی ہیں اور ایک مسلسل تصویر بناتی ہیں۔ یہ ان سیٹوں کے لیے موزوں ہے جہاں تصاویر منظر یا رنگ پیلیٹ شیئر کرتی ہیں۔</p>\n<p>بغیر سرحد تب بہترین کام کرتا ہے جب تصاویر لہجے میں ایک جیسی ہوں۔ ایک ہی روشنی والی ساحل تصاویر کا سیٹ لمحوں کے پینوراما میں مل جاتا ہے، جبکہ ملی ہوئی تصاویر کا سیٹ بکھرا لگتا ہے۔</p>\n<p>بغیر سرحد والا لے آؤٹ فوٹو وال اثر کے لیے استعمال کریں، جہاں کولاج ٹکڑوں سے بنی ایک بڑی تصویر محسوس ہونی چاہیے۔ یہ کولاج کا سب سے قریبی روپ ہے جو ایک تصویر کی طرح لگتا ہے۔</p>\n<p>ایکسپورٹ سے پہلے سیون چیک کریں۔ بغیر سرحد والے کولاج میں مماثلت چھپانے کے لیے کوئی خلا نہیں، اس لیے اپنے پڑوسی سے بہت تاریک یا گرم تصویر نظر آنے والی لکیر دکھاتی ہے۔</p>\n<h2 id=\"mixing-orientations\">سمتیں ملانا</h2>\n<p>کولاج اکثر پورٹریٹ اور لینڈ اسکیپ تصاویر ملاتا ہے، اور لے آؤٹ کو ملاوٹ سنبھالنی چاہیے۔ گرڈ اسے بہترین سنبھالتے ہیں، کیونکہ ہر سیل مربع ہوتا ہے اور Cover فٹ کراپ کرتا ہے۔</p>\n<p>پٹیاں ملی ہوئی سمت کو کم اچھی طرح سنبھالتی ہیں۔ افقی پٹی میں پورٹریٹ تصویر چوڑی قطار میں لمبا سیل بن جاتی ہے، جو پٹی کو غیر متوازن کرتی ہے۔</p>\n<p>جب ملاوٹ مضبوط ہو تو گرڈ استعمال کریں اور فٹ کو کام کرنے دیں۔ ہر سیل میں خراب کراپ چیک کریں، کیونکہ مربع سیل میں پورٹریٹ تصویر اپنا اوپر اور نیچے کھو دیتی ہے۔</p>\n<p>متبادل طور پر، کولاج بنانے سے پہلے تصاویر کو مستقل سمت میں کراپ کریں۔ پورٹریٹ اور لینڈ اسکیپ ماخذ سے مربع کراپ کا سیٹ مکمل گرڈ دیتا ہے۔</p>\n<h2 id=\"choosing-a-layout-for-the-purpose\">مقصد کے لیے لے آؤٹ چننا</h2>\n<p>پہلے لے آؤٹ کو منزل سے ملائیں۔ فیڈ پوسٹ مربع گرڈ چاہتی ہے، اسٹوری عمودی پٹی چاہتی ہے، اور بینر افقی پٹی چاہتا ہے۔ شکل منزل سے ملنی چاہیے۔</p>\n<p>پھر لے آؤٹ کو کہانی سے ملائیں۔ برابر لمحے گرڈ چاہتے ہیں، ترتیب پٹی چاہتی ہے، ہیرو لمحہ فیچر لے آؤٹ چاہتا ہے، اور احساس موڈ بورڈ چاہتا ہے۔</p>\n<p>آخر میں، لے آؤٹ کو تصویر تعداد سے ملائیں۔ چار تصاویر 2 بائی 2 گرڈ چاہتی ہیں، نو 3 بائی 3 گرڈ چاہتی ہیں، اور دو پٹی چاہتی ہیں۔ جو لے آؤٹ تعداد سے لڑے وہ زبردستی لگتا ہے۔</p>\n<p>جب دو لے آؤٹ دونوں فٹ ہوں تو دونوں بنائیں اور موازنہ کریں۔ کولاج میکر آپ کو تصاویر کھوئے بغیر لے آؤٹ بدلنے دیتا ہے، اس لیے موازنہ سیکنڈوں میں ہوتا ہے۔ تھمب نیل سائز پر موازنہ کریں۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: لے آؤٹ انتخاب</h2>\n<p>برابر لمحے: 2 بائی 2 یا 3 بائی 3 گرڈ۔ ترتیب: وقت کے لیے عمودی پٹی، موازنے کے لیے افقی پٹی۔ ہیرو لمحہ: فیچر تصویر والا لے آؤٹ۔ احساس: موڈ بورڈ۔</p>\n<p>شکل کو منزل سے، لے آؤٹ کو کہانی سے، اور لے آؤٹ کو تصویر تعداد سے ملائیں۔ جب شک ہو تو دو لے آؤٹ بنائیں اور تھمب نیل سائز پر موازنہ کریں۔</p>\n<p>مرحلہ بہ مرحلہ بنانے کے لیے <a href=\"/ur/blog/photo-collage-kaise-banayein/\">How to Make a Photo Collage</a> پڑھیں، اور مکمل گائیڈ کے لیے <a href=\"/ur/blog/tasveer-collage-maker-rehnumai/\">Photo Collage Maker: Complete Guide</a> پڑھیں۔ اپنا کولاج <a href=\"/ur/tasveer-collage-maker/\">image collage maker</a> سے بنائیں۔</p>\n";

